INSERT IGNORE INTO `lang_mgr` (`lang_key`, `zh`, `en`, `tc`, `de`, `es`, `fr`, `idn`, `jp`, `ko`, `my`, `th`, `vi`, `pt`, `rus`, `blr`, `ida`, `sa`, `ar`, `it`, `remark`) VALUES ('home_adv_title', '为活跃交易者打造的高级交易体验', 'An advanced trading experience built for active traders', '為活躍交易者打造的高級交易體驗', 'Ein erweitertes Trading-Erlebnis für aktive Trader', 'Una experiencia de trading avanzada para traders activos', 'Une expérience de trading avancée conçue pour les traders actifs', 'Pengalaman trading lanjutan untuk trader aktif', 'アクティブなトレーダーのための高度な取引体験', '활동적인 트레이더를 위한 고급 거래 경험', 'Pengalaman dagangan lanjutan untuk pedagang aktif', 'ประสบการณ์เทรดขั้นสูงสำหรับเทรดเดอร์ที่ใช้งานจริง', 'Trải nghiệm giao dịch nâng cao dành cho nhà giao dịch năng động', 'Uma experiência de trading avançada para traders ativos', 'Продвинутый торговый опыт для активных трейдеров', 'Пашыраны гандлёвы досвед для актыўных трэйдараў', 'सक्रिय ट्रेडरों के लिए उन्नत ट्रेडिंग अनुभव', 'تجربة تداول متقدمة مصممة للمتداولين النشطين', 'تجربة تداول متقدمة مصممة للمتداولين النشطين', 'Un’esperienza di trading avanzata per trader attivi', '首页高级交易');
INSERT IGNORE INTO `lang_mgr` (`lang_key`, `zh`, `en`, `tc`, `de`, `es`, `fr`, `idn`, `jp`, `ko`, `my`, `th`, `vi`, `pt`, `rus`, `blr`, `ida`, `sa`, `ar`, `it`, `remark`) VALUES ('home_adv_subtitle', '专业图表、实时行情、深度盘口和清晰的执行路径，帮助你更快看懂市场并完成交易。', 'Professional charts, real-time quotes, market depth, and clear execution paths help you understand the market faster and complete trades.', '專業圖表、即時行情、深度盤口和清晰的執行路徑，幫助你更快看懂市場並完成交易。', 'Professionelle Charts, Echtzeitkurse, Markttiefe und klare Ausführungspfade helfen dir, den Markt schneller zu verstehen und Trades abzuschließen.', 'Gráficos profesionales, cotizaciones en tiempo real, profundidad de mercado y rutas de ejecución claras te ayudan a entender el mercado más rápido y completar operaciones.', 'Des graphiques professionnels, des cours en temps réel, la profondeur du marché et des parcours d’exécution clairs vous aident à comprendre le marché plus vite et à finaliser vos transactions.', 'Grafik profesional, harga real-time, kedalaman pasar, dan alur eksekusi yang jelas membantu Anda memahami pasar lebih cepat dan menyelesaikan transaksi.', 'プロ向けチャート、リアルタイム相場、板情報、明確な執行ルートで、市場をより早く把握して取引を完了できます。', '전문 차트, 실시간 시세, 호가 깊이, 명확한 실행 경로로 시장을 더 빠르게 이해하고 거래를 완료할 수 있습니다.', 'Carta profesional, sebut harga masa nyata, kedalaman pasaran dan laluan pelaksanaan yang jelas membantu anda memahami pasaran dengan lebih cepat dan menyelesaikan dagangan.', 'กราฟมืออาชีพ ราคาตลาดแบบเรียลไทม์ ความลึกของตลาด และเส้นทางส่งคำสั่งที่ชัดเจน ช่วยให้คุณเข้าใจตลาดและเทรดได้เร็วขึ้น', 'Biểu đồ chuyên nghiệp, giá theo thời gian thực, độ sâu thị trường và quy trình khớp lệnh rõ ràng giúp bạn hiểu thị trường nhanh hơn và hoàn tất giao dịch.', 'Gráficos profissionais, cotações em tempo real, profundidade de mercado e caminhos claros de execução ajudam você a entender o mercado mais rápido e concluir operações.', 'Профессиональные графики, котировки в реальном времени, стакан заявок и понятные пути исполнения помогают быстрее понимать рынок и совершать сделки.', 'Прафесійныя графікі, каціроўкі ў рэальным часе, глыбіня рынку і зразумелыя шляхі выканання дапамагаюць хутчэй разумець рынак і здзяйсняць здзелкі.', 'पेशेवर चार्ट, रियल-टाइम भाव, मार्केट डेप्थ और स्पष्ट निष्पादन मार्ग आपको बाजार तेजी से समझने और ट्रेड पूरा करने में मदद करते हैं।', 'تساعدك الرسوم البيانية الاحترافية والأسعار الفورية وعمق السوق ومسارات التنفيذ الواضحة على فهم السوق بشكل أسرع وإتمام التداول.', 'تساعدك الرسوم البيانية الاحترافية والأسعار الفورية وعمق السوق ومسارات التنفيذ الواضحة على فهم السوق بشكل أسرع وإتمام التداول.', 'Grafici professionali, quotazioni in tempo reale, profondità di mercato e percorsi di esecuzione chiari aiutano a capire il mercato più velocemente e completare le operazioni.', '首页高级交易');
