INSERT IGNORE INTO `lang_mgr` (`lang_key`, `zh`, `en`, `tc`, `de`, `es`, `fr`, `idn`, `jp`, `ko`, `my`, `th`, `vi`, `pt`, `rus`, `blr`, `ida`, `sa`, `ar`, `it`, `remark`) VALUES ('home_adv_tools_subtitle', '把复杂数据整理成可快速判断的交易界面。', 'Organize complex data into a trading interface for quick decisions.', '把複雜資料整理成可快速判斷的交易介面。', 'Komplexe Daten werden zu einer Trading-Oberfläche für schnelle Entscheidungen geordnet.', 'Organiza datos complejos en una interfaz de trading para decisiones rápidas.', 'Organisez les données complexes dans une interface de trading conçue pour décider rapidement.', 'Susun data kompleks menjadi antarmuka trading untuk keputusan cepat.', '複雑なデータを素早く判断できる取引画面に整理します。', '복잡한 데이터를 빠르게 판단할 수 있는 거래 화면으로 정리합니다.', 'Susun data kompleks menjadi antara muka dagangan untuk keputusan pantas.', 'จัดข้อมูลซับซ้อนให้อยู่ในหน้าจอเทรดที่ตัดสินใจได้รวดเร็ว', 'Sắp xếp dữ liệu phức tạp thành giao diện giao dịch giúp ra quyết định nhanh.', 'Organize dados complexos em uma interface de trading para decisões rápidas.', 'Сложные данные организованы в торговый интерфейс для быстрых решений.', 'Складаныя даныя арганізаваны ў гандлёвы інтэрфейс для хуткіх рашэнняў.', 'जटिल डेटा को तेज निर्णय लेने वाले ट्रेडिंग इंटरफेस में व्यवस्थित करें।', 'تنظيم البيانات المعقدة في واجهة تداول تساعد على اتخاذ قرارات سريعة.', 'تنظيم البيانات المعقدة في واجهة تداول تساعد على اتخاذ قرارات سريعة.', 'Organizza dati complessi in un’interfaccia di trading per decisioni rapide.', '首页高级交易');
INSERT IGNORE INTO `lang_mgr` (`lang_key`, `zh`, `en`, `tc`, `de`, `es`, `fr`, `idn`, `jp`, `ko`, `my`, `th`, `vi`, `pt`, `rus`, `blr`, `ida`, `sa`, `ar`, `it`, `remark`) VALUES ('home_adv_tool_chart', '专业 K 线图表', 'Professional Candlestick Charts', '專業 K 線圖表', 'Professionelle Kerzencharts', 'Gráficos de velas profesionales', 'Graphiques en chandeliers professionnels', 'Grafik Candlestick Profesional', 'プロ向けローソク足チャート', '전문 캔들 차트', 'Carta Candlestick Profesional', 'กราฟแท่งเทียนมืออาชีพ', 'Biểu đồ nến chuyên nghiệp', 'Gráficos de candlestick profissionais', 'Профессиональные свечные графики', 'Прафесійныя свечныя графікі', 'पेशेवर कैंडलस्टिक चार्ट', 'رسوم شموع احترافية', 'رسوم شموع احترافية', 'Grafici candlestick professionali', '首页高级交易');
INSERT IGNORE INTO `lang_mgr` (`lang_key`, `zh`, `en`, `tc`, `de`, `es`, `fr`, `idn`, `jp`, `ko`, `my`, `th`, `vi`, `pt`, `rus`, `blr`, `ida`, `sa`, `ar`, `it`, `remark`) VALUES ('home_adv_tool_chart_desc', '多周期图表与指标分析，随时跟踪价格结构。', 'Multi-timeframe charts and indicator analysis help track price structure anytime.', '多週期圖表與指標分析，隨時追蹤價格結構。', 'Charts über mehrere Zeiträume und Indikatoranalysen verfolgen jederzeit die Preisstruktur.', 'Gráficos de varios periodos e indicadores para seguir la estructura del precio en cualquier momento.', 'Graphiques multi-périodes et analyse des indicateurs pour suivre la structure des prix à tout moment.', 'Grafik multi-periode dan analisis indikator membantu melacak struktur harga kapan saja.', '複数時間軸のチャートと指標分析で、価格構造をいつでも追跡できます。', '다중 주기 차트와 지표 분석으로 언제든 가격 구조를 추적합니다.', 'Carta berbilang tempoh dan analisis indikator membantu menjejak struktur harga pada bila-bila masa.', 'กราฟหลายช่วงเวลาและอินดิเคเตอร์ช่วยติดตามโครงสร้างราคาได้ทุกเวลา', 'Biểu đồ đa khung thời gian và phân tích chỉ báo giúp theo dõi cấu trúc giá bất cứ lúc nào.', 'Gráficos de múltiplos períodos e indicadores ajudam a acompanhar a estrutura de preço a qualquer momento.', 'Графики разных периодов и индикаторы помогают отслеживать структуру цены в любое время.', 'Графікі розных перыядаў і індыкатары дапамагаюць адсочваць структуру цаны ў любы час.', 'कई टाइमफ्रेम चार्ट और इंडिकेटर विश्लेषण से कभी भी मूल्य संरचना ट्रैक करें।', 'تساعد الرسوم متعددة الفترات وتحليل المؤشرات على متابعة بنية السعر في أي وقت.', 'تساعد الرسوم متعددة الفترات وتحليل المؤشرات على متابعة بنية السعر في أي وقت.', 'Grafici multi-periodo e analisi degli indicatori aiutano a seguire la struttura del prezzo in ogni momento.', '首页高级交易');
INSERT IGNORE INTO `lang_mgr` (`lang_key`, `zh`, `en`, `tc`, `de`, `es`, `fr`, `idn`, `jp`, `ko`, `my`, `th`, `vi`, `pt`, `rus`, `blr`, `ida`, `sa`, `ar`, `it`, `remark`) VALUES ('home_adv_tool_depth', '实时深度盘口', 'Real-Time Market Depth', '即時深度盤口', 'Echtzeit-Markttiefe', 'Profundidad de mercado en tiempo real', 'Profondeur de marché en temps réel', 'Kedalaman Pasar Real-Time', 'リアルタイム板情報', '실시간 호가 깊이', 'Kedalaman Pasaran Masa Nyata', 'ความลึกตลาดแบบเรียลไทม์', 'Độ sâu thị trường theo thời gian thực', 'Profundidade de mercado em tempo real', 'Стакан заявок в реальном времени', 'Глыбіня рынку ў рэальным часе', 'रियल-टाइम मार्केट डेप्थ', 'عمق السوق في الوقت الفعلي', 'عمق السوق في الوقت الفعلي', 'Profondità di mercato in tempo reale', '首页高级交易');
INSERT IGNORE INTO `lang_mgr` (`lang_key`, `zh`, `en`, `tc`, `de`, `es`, `fr`, `idn`, `jp`, `ko`, `my`, `th`, `vi`, `pt`, `rus`, `blr`, `ida`, `sa`, `ar`, `it`, `remark`) VALUES ('home_adv_tool_depth_desc', '同步买卖盘变化，辅助判断流动性和价差。', 'Synchronize bid and ask changes to help assess liquidity and spreads.', '同步買賣盤變化，輔助判斷流動性和價差。', 'Synchronisierte Kauf- und Verkaufsänderungen helfen bei der Einschätzung von Liquidität und Spreads.', 'Sincroniza cambios de compra y venta para evaluar liquidez y diferenciales.', 'Synchronisez les variations des ordres d’achat et de vente pour évaluer la liquidité et les écarts.', 'Sinkronkan perubahan bid dan ask untuk membantu menilai likuiditas dan spread.', '買い板と売り板の変化を同期し、流動性とスプレッド判断を支援します。', '매수·매도 호가 변화를 동기화해 유동성과 스프레드 판단을 돕습니다.', 'Segerakkan perubahan beli dan jual untuk membantu menilai kecairan dan spread.', 'ซิงค์การเปลี่ยนแปลงฝั่งซื้อขายเพื่อช่วยประเมินสภาพคล่องและสเปรด', 'Đồng bộ thay đổi bên mua và bán để hỗ trợ đánh giá thanh khoản và chênh lệch giá.', 'Sincronize mudanças de compra e venda para avaliar liquidez e spread.', 'Синхронизация изменений заявок покупки и продажи помогает оценивать ликвидность и спред.', 'Сінхранізацыя змяненняў заявак куплі і продажу дапамагае ацэньваць ліквіднасць і спрэды.', 'बिड और आस्क बदलाव सिंक करके तरलता और स्प्रेड समझने में मदद मिलती है।', 'مزامنة تغيّرات أوامر الشراء والبيع للمساعدة في تقييم السيولة والفروقات.', 'مزامنة تغيّرات أوامر الشراء والبيع للمساعدة في تقييم السيولة والفروقات.', 'Sincronizza le variazioni di acquisto e vendita per valutare liquidità e spread.', '首页高级交易');
INSERT IGNORE INTO `lang_mgr` (`lang_key`, `zh`, `en`, `tc`, `de`, `es`, `fr`, `idn`, `jp`, `ko`, `my`, `th`, `vi`, `pt`, `rus`, `blr`, `ida`, `sa`, `ar`, `it`, `remark`) VALUES ('home_adv_tool_fee', '费用更透明', 'More Transparent Fees', '費用更透明', 'Transparentere Gebühren', 'Comisiones más transparentes', 'Frais plus transparents', 'Biaya Lebih Transparan', 'より透明な手数料', '더 투명한 수수료', 'Yuran Lebih Telus', 'ค่าธรรมเนียมโปร่งใสมากขึ้น', 'Phí minh bạch hơn', 'Taxas mais transparentes', 'Более прозрачные комиссии', 'Больш празрыстыя камісіі', 'अधिक पारदर्शी शुल्क', 'رسوم أكثر شفافية', 'رسوم أكثر شفافية', 'Commissioni più trasparenti', '首页高级交易');
INSERT IGNORE INTO `lang_mgr` (`lang_key`, `zh`, `en`, `tc`, `de`, `es`, `fr`, `idn`, `jp`, `ko`, `my`, `th`, `vi`, `pt`, `rus`, `blr`, `ida`, `sa`, `ar`, `it`, `remark`) VALUES ('home_adv_tool_fee_desc', '交易前看清价格、数量和费用，减少不必要成本。', 'Review price, quantity, and fees before trading to reduce unnecessary costs.', '交易前看清價格、數量和費用，減少不必要成本。', 'Prüfe Preis, Menge und Gebühren vor dem Handel, um unnötige Kosten zu reduzieren.', 'Revisa precio, cantidad y comisiones antes de operar para reducir costos innecesarios.', 'Vérifiez le prix, la quantité et les frais avant de trader afin de réduire les coûts inutiles.', 'Periksa harga, jumlah, dan biaya sebelum trading untuk mengurangi biaya yang tidak perlu.', '取引前に価格、数量、手数料を確認し、不要なコストを抑えます。', '거래 전에 가격, 수량, 수수료를 확인해 불필요한 비용을 줄입니다.', 'Semak harga, kuantiti dan yuran sebelum berdagang untuk mengurangkan kos yang tidak perlu.', 'ตรวจสอบราคา จำนวน และค่าธรรมเนียมก่อนเทรด เพื่อลดต้นทุนที่ไม่จำเป็น', 'Xem rõ giá, số lượng và phí trước khi giao dịch để giảm chi phí không cần thiết.', 'Confira preço, quantidade e taxas antes de negociar para reduzir custos desnecessários.', 'Проверяйте цену, количество и комиссии перед сделкой, чтобы снизить лишние расходы.', 'Правярайце цану, колькасць і камісіі перад здзелкай, каб знізіць лішнія выдаткі.', 'ट्रेड से पहले कीमत, मात्रा और शुल्क देखें ताकि अनावश्यक लागत कम हो।', 'راجع السعر والكمية والرسوم قبل التداول لتقليل التكاليف غير الضرورية.', 'راجع السعر والكمية والرسوم قبل التداول لتقليل التكاليف غير الضرورية.', 'Controlla prezzo, quantità e commissioni prima di fare trading per ridurre costi inutili.', '首页高级交易');
