INSERT IGNORE INTO `lang_mgr` (`lang_key`, `zh`, `en`, `tc`, `de`, `es`, `fr`, `idn`, `jp`, `ko`, `my`, `th`, `vi`, `pt`, `rus`, `blr`, `ida`, `sa`, `ar`, `it`, `remark`) VALUES ('home_adv_order_subtitle', '按当前项目已有交易能力展示，不做空承诺。', 'Displays current trading capabilities without overpromising.', '按目前專案已有交易能力展示，不做空承諾。', 'Zeigt vorhandene Trading-Funktionen ohne leere Versprechen.', 'Muestra las capacidades de trading existentes sin promesas vacías.', 'Présente les capacités de trading existantes sans promesses excessives.', 'Menampilkan kemampuan trading yang tersedia tanpa janji kosong.', '現在の取引機能に基づいて表示し、過度な約束はしません。', '현재 제공되는 거래 기능만 표시하며 과도한 약속을 하지 않습니다.', 'Memaparkan keupayaan dagangan sedia ada tanpa janji kosong.', 'แสดงความสามารถการเทรดที่มีอยู่จริง โดยไม่ให้คำมั่นเกินจริง', 'Hiển thị năng lực giao dịch hiện có, không hứa hẹn quá mức.', 'Exibe os recursos de trading existentes sem prometer além do possível.', 'Показывает текущие торговые возможности без пустых обещаний.', 'Паказвае наяўныя гандлёвыя магчымасці без пустых абяцанняў.', 'मौजूदा ट्रेडिंग क्षमताएं दिखाता है, बिना खोखे वादों के।', 'يعرض قدرات التداول الحالية دون وعود مبالغ فيها.', 'يعرض قدرات التداول الحالية دون وعود مبالغ فيها.', 'Mostra le capacità di trading attuali senza promesse eccessive.', '首页高级交易');
INSERT IGNORE INTO `lang_mgr` (`lang_key`, `zh`, `en`, `tc`, `de`, `es`, `fr`, `idn`, `jp`, `ko`, `my`, `th`, `vi`, `pt`, `rus`, `blr`, `ida`, `sa`, `ar`, `it`, `remark`) VALUES ('home_adv_exec_order', '多种交易入口', 'Multiple trading entry points', '多種交易入口', 'Mehrere Trading-Einstiege', 'Múltiples entradas de trading', 'Plusieurs points d’entrée de trading', 'Beberapa pintu masuk trading', '複数の取引入口', '다양한 거래 진입 경로', 'Pelbagai pintu masuk dagangan', 'หลายช่องทางเข้าสู่การเทรด', 'Nhiều lối vào giao dịch', 'Múltiplos pontos de entrada de trading', 'Несколько точек входа в торговлю', 'Некалькі кропак уваходу ў гандаль', 'कई ट्रेडिंग एंट्री पॉइंट', 'مداخل تداول متعددة', 'مداخل تداول متعددة', 'Più accessi al trading', '首页高级交易');
INSERT IGNORE INTO `lang_mgr` (`lang_key`, `zh`, `en`, `tc`, `de`, `es`, `fr`, `idn`, `jp`, `ko`, `my`, `th`, `vi`, `pt`, `rus`, `blr`, `ida`, `sa`, `ar`, `it`, `remark`) VALUES ('home_adv_exec_order_desc', '从行情、详情页或默认交易品种快速进入下单流程。', 'Quickly enter the order flow from markets, detail pages, or default trading products.', '從行情、詳情頁或預設交易品種快速進入下單流程。', 'Wechsle schnell von Märkten, Detailseiten oder Standardprodukten in den Orderprozess.', 'Entra rápidamente al flujo de órdenes desde mercados, páginas de detalle o productos predeterminados.', 'Accédez rapidement au parcours d’ordre depuis les marchés, les pages de détail ou les produits par défaut.', 'Masuk cepat ke alur order dari pasar, halaman detail, atau produk trading default.', '相場、詳細ページ、またはデフォルト取引銘柄から注文フローへすばやく進めます。', '시세, 상세 페이지 또는 기본 거래 종목에서 주문 흐름으로 빠르게 이동합니다.', 'Masuk pantas ke aliran pesanan daripada pasaran, halaman butiran atau produk dagangan lalai.', 'เข้าสู่ขั้นตอนส่งคำสั่งได้รวดเร็วจากตลาด หน้ารายละเอียด หรือสินค้าที่ตั้งไว้', 'Nhanh chóng vào quy trình đặt lệnh từ thị trường, trang chi tiết hoặc sản phẩm giao dịch mặc định.', 'Entre rapidamente no fluxo de ordens a partir de mercados, detalhes ou produtos padrão.', 'Быстро переходите к размещению ордера из рынков, страниц деталей или стандартных торговых продуктов.', 'Хутка пераходзьце да размяшчэння ордара з рынкаў, старонак дэталяў або стандартных прадуктаў.', 'मार्केट, विवरण पेज या डिफॉल्ट ट्रेडिंग प्रोडक्ट से जल्दी ऑर्डर प्रक्रिया में जाएं।', 'ادخل بسرعة إلى مسار الأمر من الأسواق أو صفحات التفاصيل أو منتجات التداول الافتراضية.', 'ادخل بسرعة إلى مسار الأمر من الأسواق أو صفحات التفاصيل أو منتجات التداول الافتراضية.', 'Accedi rapidamente al flusso ordini da mercati, pagine dettaglio o prodotti predefiniti.', '首页高级交易');
INSERT IGNORE INTO `lang_mgr` (`lang_key`, `zh`, `en`, `tc`, `de`, `es`, `fr`, `idn`, `jp`, `ko`, `my`, `th`, `vi`, `pt`, `rus`, `blr`, `ida`, `sa`, `ar`, `it`, `remark`) VALUES ('home_adv_exec_speed', '行情持续刷新', 'Quotes keep refreshing', '行情持續刷新', 'Kurse werden laufend aktualisiert', 'Los precios se actualizan continuamente', 'Les cours se rafraîchissent en continu', 'Harga terus diperbarui', '相場は継続的に更新', '시세 지속 갱신', 'Harga terus disegar semula', 'ราคาตลาดรีเฟรชต่อเนื่อง', 'Giá được làm mới liên tục', 'Cotações sempre atualizadas', 'Котировки постоянно обновляются', 'Каціроўкі пастаянна абнаўляюцца', 'भाव लगातार रीफ्रेश होते हैं', 'تحديث مستمر للأسعار', 'تحديث مستمر للأسعار', 'Quotazioni aggiornate continuamente', '首页高级交易');
INSERT IGNORE INTO `lang_mgr` (`lang_key`, `zh`, `en`, `tc`, `de`, `es`, `fr`, `idn`, `jp`, `ko`, `my`, `th`, `vi`, `pt`, `rus`, `blr`, `ida`, `sa`, `ar`, `it`, `remark`) VALUES ('home_adv_exec_speed_desc', '首页行情定时同步，价格变化不用反复手动刷新。', 'Home market data syncs on schedule, so price changes do not require repeated manual refresh.', '首頁行情定時同步，價格變化不用反覆手動刷新。', 'Die Startseitenkurse werden regelmäßig synchronisiert, manuelles Aktualisieren ist nicht ständig nötig.', 'Los datos de mercado de inicio se sincronizan periódicamente, sin refrescar manualmente una y otra vez.', 'Les données de marché de l’accueil se synchronisent régulièrement, sans actualisation manuelle répétée.', 'Data pasar beranda disinkronkan terjadwal, sehingga perubahan harga tidak perlu disegarkan manual berulang kali.', 'ホームの相場は定期同期され、価格変動のたびに手動更新する必要がありません。', '홈 시세가 정기적으로 동기화되어 가격 변화를 반복해서 수동 새로고침할 필요가 없습니다.', 'Data pasaran laman utama disegerakkan secara berkala, jadi perubahan harga tidak perlu disegar semula secara manual berulang kali.', 'ข้อมูลตลาดหน้าแรกซิงค์ตามเวลา จึงไม่ต้องรีเฟรชเองซ้ำ ๆ เมื่อราคาเปลี่ยน', 'Dữ liệu thị trường trang chủ được đồng bộ định kỳ, không cần làm mới thủ công nhiều lần khi giá thay đổi.', 'Os dados da página inicial sincronizam periodicamente, sem precisar atualizar manualmente a cada mudança de preço.', 'Данные рынка на главной странице синхронизируются по расписанию, поэтому не нужно постоянно обновлять вручную.', 'Даныя рынку на галоўнай старонцы сінхранізуюцца па раскладзе, таму не трэба пастаянна абнаўляць уручную.', 'होम मार्केट डेटा समय-समय पर सिंक होता है, इसलिए कीमत बदलने पर बार-बार मैनुअल रीफ्रेश नहीं चाहिए।', 'تتزامن بيانات السوق في الصفحة الرئيسية بانتظام، فلا تحتاج إلى تحديث يدوي متكرر عند تغير الأسعار.', 'تتزامن بيانات السوق في الصفحة الرئيسية بانتظام، فلا تحتاج إلى تحديث يدوي متكرر عند تغير الأسعار.', 'I dati di mercato in home si sincronizzano periodicamente, senza aggiornamenti manuali ripetuti.', '首页高级交易');
INSERT IGNORE INTO `lang_mgr` (`lang_key`, `zh`, `en`, `tc`, `de`, `es`, `fr`, `idn`, `jp`, `ko`, `my`, `th`, `vi`, `pt`, `rus`, `blr`, `ida`, `sa`, `ar`, `it`, `remark`) VALUES ('home_adv_exec_risk', '交易前确认', 'Confirm before trading', '交易前確認', 'Vor dem Handel bestätigen', 'Confirmar antes de operar', 'Confirmer avant de trader', 'Konfirmasi sebelum trading', '取引前に確認', '거래 전 확인', 'Sahkan sebelum berdagang', 'ยืนยันก่อนเทรด', 'Xác nhận trước khi giao dịch', 'Confirmar antes de negociar', 'Подтверждение перед торговлей', 'Пацвярджэнне перад гандлем', 'ट्रेड से पहले पुष्टि करें', 'التأكيد قبل التداول', 'التأكيد قبل التداول', 'Conferma prima del trading', '首页高级交易');
INSERT IGNORE INTO `lang_mgr` (`lang_key`, `zh`, `en`, `tc`, `de`, `es`, `fr`, `idn`, `jp`, `ko`, `my`, `th`, `vi`, `pt`, `rus`, `blr`, `ida`, `sa`, `ar`, `it`, `remark`) VALUES ('home_adv_exec_risk_desc', '订单、资产与风控状态沿用现有项目流程，操作更稳。', 'Orders, assets, and risk-control status follow existing project flows for steadier operation.', '訂單、資產與風控狀態沿用現有專案流程，操作更穩。', 'Orders, Assets und Risikostatus folgen bestehenden Projektabläufen für stabilere Vorgänge.', 'Órdenes, activos y control de riesgo siguen los flujos existentes para operar con más estabilidad.', 'Les ordres, les actifs et le statut de risque suivent les processus existants pour une utilisation plus stable.', 'Order, aset, dan status kontrol risiko mengikuti alur proyek yang ada agar operasi lebih stabil.', '注文、資産、リスク管理状態は既存フローに沿い、より安定して操作できます。', '주문, 자산, 리스크 관리 상태는 기존 프로젝트 흐름을 따라 더 안정적으로 운영됩니다.', 'Pesanan, aset dan status kawalan risiko mengikut aliran projek sedia ada untuk operasi yang lebih stabil.', 'คำสั่ง สินทรัพย์ และสถานะควบคุมความเสี่ยงใช้กระบวนการเดิมของระบบ เพื่อการใช้งานที่มั่นคงขึ้น', 'Lệnh, tài sản và trạng thái kiểm soát rủi ro dùng quy trình hiện có, giúp thao tác ổn định hơn.', 'Ordens, ativos e controle de risco seguem os fluxos existentes para uma operação mais estável.', 'Ордера, активы и статус риск-контроля следуют существующим процессам для более стабильной работы.', 'Ордары, актывы і статус рызыка-кантролю ідуць па існых працэсах для больш стабільнай працы.', 'ऑर्डर, एसेट और रिस्क-कंट्रोल स्थिति मौजूदा प्रक्रिया का पालन करते हैं, जिससे संचालन अधिक स्थिर होता है।', 'تتبع الأوامر والأصول وحالة التحكم بالمخاطر العمليات الحالية لتشغيل أكثر استقرارًا.', 'تتبع الأوامر والأصول وحالة التحكم بالمخاطر العمليات الحالية لتشغيل أكثر استقرارًا.', 'Ordini, asset e stato del controllo rischio seguono i flussi esistenti per operazioni più stabili.', '首页高级交易');
INSERT IGNORE INTO `lang_mgr` (`lang_key`, `zh`, `en`, `tc`, `de`, `es`, `fr`, `idn`, `jp`, `ko`, `my`, `th`, `vi`, `pt`, `rus`, `blr`, `ida`, `sa`, `ar`, `it`, `remark`) VALUES ('home_adv_earn_title', '交易之外，也能配置收益', 'Configure earnings beyond trading', '交易之外，也能配置收益', 'Erträge auch außerhalb des Tradings konfigurieren', 'Configura rendimientos más allá del trading', 'Configurez des rendements au-delà du trading', 'Atur hasil di luar trading', '取引以外でも収益を設定', '거래 외에도 수익 구성', 'Konfigurasi hasil selain dagangan', 'จัดสรรผลตอบแทนนอกเหนือจากการเทรด', 'Cấu hình lợi nhuận ngoài giao dịch', 'Configure rendimentos além do trading', 'Настраивайте доходность помимо торговли', 'Наладжвайце даходнасць па-за гандлем', 'ट्रेडिंग के अलावा भी आय配置 करें', 'إعداد العوائد خارج التداول', 'إعداد العوائد خارج التداول', 'Configura rendimenti oltre il trading', '首页高级交易');
INSERT IGNORE INTO `lang_mgr` (`lang_key`, `zh`, `en`, `tc`, `de`, `es`, `fr`, `idn`, `jp`, `ko`, `my`, `th`, `vi`, `pt`, `rus`, `blr`, `ida`, `sa`, `ar`, `it`, `remark`) VALUES ('home_adv_earn_subtitle', '将项目已有质押、锁仓能力包装成更清晰的资产增长入口。', 'Package existing staking and lock-up capabilities into clearer asset growth entry points.', '將專案已有質押、鎖倉能力包裝成更清晰的資產增長入口。', 'Bestehende Staking- und Lock-up-Funktionen werden als klarere Einstiege für Asset-Wachstum dargestellt.', 'Agrupa las capacidades existentes de staking y bloqueo en entradas más claras para crecimiento de activos.', 'Présentez les fonctions existantes de staking et de blocage comme des accès plus clairs à la croissance des actifs.', 'Kemas kemampuan staking dan lock-up yang ada menjadi pintu masuk pertumbuhan aset yang lebih jelas.', '既存のステーキングとロック機能を、より分かりやすい資産成長の入口として整理します。', '기존 스테이킹과 락업 기능을 더 명확한 자산 성장入口으로 구성합니다.', 'Bungkus keupayaan staking dan lock-up sedia ada sebagai pintu masuk pertumbuhan aset yang lebih jelas.', 'นำความสามารถด้าน staking และ lock-up ที่มีอยู่มาจัดเป็นทางเข้าสู่การเติบโตของสินทรัพย์ที่ชัดเจนขึ้น', 'Đóng gói năng lực staking và khóa hiện có thành lối vào tăng trưởng tài sản rõ ràng hơn.', 'Organize recursos existentes de staking e bloqueio em entradas mais claras para crescimento de ativos.', 'Существующие функции стейкинга и блокировки представлены как более понятные входы для роста активов.', 'Існыя функцыі стэйкінгу і блакіроўкі прадстаўлены як больш зразумелыя ўваходы для росту актываў.', 'मौजूदा स्टेकिंग और लॉक-अप क्षमताओं को स्पष्ट एसेट वृद्धि入口 के रूप में प्रस्तुत करें।', 'تجميع قدرات التخزين والقفل الحالية في مداخل أوضح لنمو الأصول.', 'تجميع قدرات التخزين والقفل الحالية في مداخل أوضح لنمو الأصول.', 'Racchiude staking e lock-up esistenti in accessi più chiari alla crescita degli asset.', '首页高级交易');
