INSERT IGNORE INTO `lang_mgr` (`lang_key`, `zh`, `en`, `tc`, `de`, `es`, `fr`, `idn`, `jp`, `ko`, `my`, `th`, `vi`, `pt`, `rus`, `blr`, `ida`, `sa`, `ar`, `it`, `remark`) VALUES ('home_adv_earn_lock_desc', '固定周期，收益规则更明确。', 'Fixed terms with clearer yield rules.', '固定週期，收益規則更明確。', 'Feste Laufzeiten mit klareren Ertragsregeln.', 'Plazos fijos con reglas de rendimiento más claras.', 'Durées fixes avec des règles de rendement plus claires.', 'Periode tetap dengan aturan hasil yang lebih jelas.', '固定期間で、収益ルールがより明確です。', '고정 기간과 더 명확한 수익 규칙을 제공합니다.', 'Tempoh tetap dengan peraturan hasil yang lebih jelas.', 'ระยะเวลาคงที่ พร้อมกติกาผลตอบแทนที่ชัดเจนขึ้น', 'Kỳ hạn cố định, quy tắc lợi nhuận rõ ràng hơn.', 'Prazos fixos com regras de rendimento mais claras.', 'Фиксированный срок и более понятные правила доходности.', 'Фіксаваны тэрмін і больш зразумелыя правілы даходнасці.', 'निश्चित अवधि और अधिक स्पष्ट आय नियम।', 'مدة ثابتة وقواعد عائد أوضح.', 'مدة ثابتة وقواعد عائد أوضح.', 'Durate fisse con regole di rendimento più chiare.', '首页高级交易');
