INSERT IGNORE INTO `lang_mgr` (`lang_key`, `zh`, `en`, `tc`, `de`, `es`, `fr`, `idn`, `jp`, `ko`, `my`, `th`, `vi`, `pt`, `rus`, `blr`, `ida`, `sa`, `ar`, `it`, `remark`) VALUES ('home_adv_earn_flex_desc', '按账户状态和产品规则参与。', 'Participate according to account status and product rules.', '按帳戶狀態和產品規則參與。', 'Teilnahme gemäß Kontostatus und Produktregeln.', 'Participa según el estado de la cuenta y las reglas del producto.', 'Participez selon le statut du compte et les règles du produit.', 'Berpartisipasi sesuai status akun dan aturan produk.', 'アカウント状態と商品ルールに応じて参加します。', '계정 상태와 상품 규칙에 따라 참여합니다.', 'Sertai mengikut status akaun dan peraturan produk.', 'เข้าร่วมตามสถานะบัญชีและกฎของผลิตภัณฑ์', 'Tham gia theo trạng thái tài khoản và quy tắc sản phẩm.', 'Participe conforme o status da conta e as regras do produto.', 'Участвуйте согласно статусу аккаунта и правилам продукта.', 'Удзельнічайце паводле статусу акаўнта і правілаў прадукту.', 'खाता स्थिति और प्रोडक्ट नियमों के अनुसार भाग लें।', 'شارك وفقًا لحالة الحساب وقواعد المنتج.', 'شارك وفقًا لحالة الحساب وقواعد المنتج.', 'Partecipa in base allo stato account e alle regole del prodotto.', '首页高级交易');
INSERT IGNORE INTO `lang_mgr` (`lang_key`, `zh`, `en`, `tc`, `de`, `es`, `fr`, `idn`, `jp`, `ko`, `my`, `th`, `vi`, `pt`, `rus`, `blr`, `ida`, `sa`, `ar`, `it`, `remark`) VALUES ('home_adv_trust_title', '安全和服务放在交易之前', 'Security and service come before trading', '安全和服務放在交易之前', 'Sicherheit und Service stehen vor dem Trading', 'Seguridad y servicio antes del trading', 'Sécurité et service avant le trading', 'Keamanan dan layanan diutamakan sebelum trading', '取引の前に安全とサービスを優先', '거래보다 안전과 서비스를 먼저', 'Keselamatan dan perkhidmatan didahulukan sebelum dagangan', 'ความปลอดภัยและบริการมาก่อนการเทรด', 'An toàn và dịch vụ đặt trước giao dịch', 'Segurança e serviço vêm antes do trading', 'Безопасность и сервис прежде торговли', 'Бяспека і сэрвіс перад гандлем', 'ट्रेडिंग से पहले सुरक्षा और सेवा', 'الأمان والخدمة قبل التداول', 'الأمان والخدمة قبل التداول', 'Sicurezza e servizio prima del trading', '首页高级交易');
INSERT IGNORE INTO `lang_mgr` (`lang_key`, `zh`, `en`, `tc`, `de`, `es`, `fr`, `idn`, `jp`, `ko`, `my`, `th`, `vi`, `pt`, `rus`, `blr`, `ida`, `sa`, `ar`, `it`, `remark`) VALUES ('home_adv_trust_subtitle', '营销层只展示项目能承接的能力，避免过度承诺。', 'The marketing layer only shows capabilities the project can support, avoiding overpromising.', '行銷層只展示專案能承接的能力，避免過度承諾。', 'Die Marketingebene zeigt nur unterstützte Projektfunktionen und vermeidet übertriebene Versprechen.', 'La capa de marketing solo muestra capacidades que el proyecto puede soportar y evita prometer de más.', 'La couche marketing ne montre que les capacités prises en charge par le projet et évite les promesses excessives.', 'Lapisan pemasaran hanya menampilkan kemampuan yang dapat didukung proyek dan menghindari janji berlebihan.', 'マーケティング層はプロジェクトが対応できる機能だけを表示し、過度な約束を避けます。', '마케팅 영역은 프로젝트가 지원할 수 있는 기능만 표시해 과도한 약속을 피합니다.', 'Lapisan pemasaran hanya memaparkan keupayaan yang boleh disokong projek dan mengelakkan janji berlebihan.', 'ส่วนการตลาดแสดงเฉพาะความสามารถที่โครงการรองรับได้จริง เพื่อหลีกเลี่ยงคำมั่นเกินจริง', 'Lớp marketing chỉ hiển thị năng lực dự án có thể hỗ trợ, tránh hứa hẹn quá mức.', 'A camada de marketing mostra apenas recursos que o projeto pode suportar, evitando promessas excessivas.', 'Маркетинговый слой показывает только возможности, которые проект реально поддерживает, избегая завышенных обещаний.', 'Маркетынгавы слой паказвае толькі магчымасці, якія праект сапраўды падтрымлівае, пазбягаючы завышаных абяцанняў.', 'मार्केटिंग लेयर केवल वही क्षमताएं दिखाती है जिन्हें प्रोजेक्ट संभाल सकता है, अतिशयोक्ति से बचते हुए।', 'تعرض طبقة التسويق فقط القدرات التي يمكن للمشروع دعمها لتجنب الوعود المبالغ فيها.', 'تعرض طبقة التسويق فقط القدرات التي يمكن للمشروع دعمها لتجنب الوعود المبالغ فيها.', 'Il livello marketing mostra solo capacità supportabili dal progetto, evitando promesse eccessive.', '首页高级交易');
INSERT IGNORE INTO `lang_mgr` (`lang_key`, `zh`, `en`, `tc`, `de`, `es`, `fr`, `idn`, `jp`, `ko`, `my`, `th`, `vi`, `pt`, `rus`, `blr`, `ida`, `sa`, `ar`, `it`, `remark`) VALUES ('home_adv_trust_asset', '资产流程清晰', 'Clear asset flows', '資產流程清晰', 'Klare Asset-Abläufe', 'Flujos de activos claros', 'Parcours d’actifs clairs', 'Alur aset yang jelas', '明確な資産フロー', '명확한 자산 흐름', 'Aliran aset yang jelas', 'ขั้นตอนสินทรัพย์ชัดเจน', 'Quy trình tài sản rõ ràng', 'Fluxos de ativos claros', 'Понятные процессы активов', 'Зразумелыя працэсы актываў', 'स्पष्ट एसेट प्रक्रियाएँ', 'مسارات أصول واضحة', 'مسارات أصول واضحة', 'Flussi asset chiari', '首页高级交易');
INSERT IGNORE INTO `lang_mgr` (`lang_key`, `zh`, `en`, `tc`, `de`, `es`, `fr`, `idn`, `jp`, `ko`, `my`, `th`, `vi`, `pt`, `rus`, `blr`, `ida`, `sa`, `ar`, `it`, `remark`) VALUES ('home_adv_trust_asset_desc', '充值、提现、资金记录都沿用现有账户体系。', 'Deposits, withdrawals, and fund records all follow the existing account system.', '充值、提現、資金記錄都沿用現有帳戶體系。', 'Einzahlungen, Auszahlungen und Kapitalaufzeichnungen folgen dem bestehenden Kontosystem.', 'Depósitos, retiros y registros de fondos siguen el sistema de cuenta existente.', 'Les dépôts, retraits et historiques de fonds suivent le système de compte existant.', 'Deposit, penarikan, dan catatan dana mengikuti sistem akun yang ada.', '入金、出金、資金記録は既存のアカウント体系に従います。', '입금, 출금, 자금 기록은 기존 계정 시스템을 따릅니다.', 'Deposit, pengeluaran dan rekod dana mengikut sistem akaun sedia ada.', 'การฝาก ถอน และบันทึกเงินใช้ระบบบัญชีเดิมทั้งหมด', 'Nạp tiền, rút tiền và lịch sử vốn đều dùng hệ thống tài khoản hiện có.', 'Depósitos, saques e registros de fundos seguem o sistema de conta existente.', 'Пополнения, выводы и записи средств следуют существующей системе аккаунтов.', 'Папаўненні, вывады і запісы сродкаў ідуць па існай сістэме акаўнтаў.', 'जमा, निकासी और फंड रिकॉर्ड मौजूदा खाता प्रणाली का पालन करते हैं।', 'تتبع عمليات الإيداع والسحب وسجلات الأموال نظام الحساب الحالي.', 'تتبع عمليات الإيداع والسحب وسجلات الأموال نظام الحساب الحالي.', 'Depositi, prelievi e registri fondi seguono il sistema account esistente.', '首页高级交易');
INSERT IGNORE INTO `lang_mgr` (`lang_key`, `zh`, `en`, `tc`, `de`, `es`, `fr`, `idn`, `jp`, `ko`, `my`, `th`, `vi`, `pt`, `rus`, `blr`, `ida`, `sa`, `ar`, `it`, `remark`) VALUES ('home_adv_trust_service', '客服支持', 'Customer support', '客服支援', 'Kundensupport', 'Atención al cliente', 'Support client', 'Dukungan pelanggan', 'カスタマーサポート', '고객 지원', 'Sokongan pelanggan', 'ฝ่ายบริการลูกค้า', 'Hỗ trợ khách hàng', 'Suporte ao cliente', 'Служба поддержки', 'Служба падтрымкі', 'ग्राहक सहायता', 'دعم العملاء', 'دعم العملاء', 'Assistenza clienti', '首页高级交易');
INSERT IGNORE INTO `lang_mgr` (`lang_key`, `zh`, `en`, `tc`, `de`, `es`, `fr`, `idn`, `jp`, `ko`, `my`, `th`, `vi`, `pt`, `rus`, `blr`, `ida`, `sa`, `ar`, `it`, `remark`) VALUES ('home_adv_trust_service_desc', '遇到认证、充值、交易问题可直接进入客服通道。', 'For verification, deposit, or trading issues, go directly to customer support.', '遇到認證、充值、交易問題可直接進入客服通道。', 'Bei Verifizierungs-, Einzahlungs- oder Trading-Problemen gelangst du direkt zum Kundensupport.', 'Para problemas de verificación, depósito o trading, entra directamente al soporte al cliente.', 'Pour les problèmes de vérification, dépôt ou trading, accédez directement au support client.', 'Untuk masalah verifikasi, deposit, atau trading, langsung masuk ke layanan pelanggan.', '認証、入金、取引の問題はカスタマーサポートへ直接進めます。', '인증, 입금, 거래 문제가 있으면 고객 지원으로 바로 이동할 수 있습니다.', 'Untuk isu pengesahan, deposit atau dagangan, terus masuk ke saluran sokongan pelanggan.', 'หากพบปัญหาการยืนยันตัวตน ฝากเงิน หรือเทรด สามารถเข้าสู่ช่องทาง客服ได้โดยตรง', 'Khi gặp vấn đề xác minh, nạp tiền hoặc giao dịch, có thể vào kênh hỗ trợ khách hàng trực tiếp.', 'Para problemas de verificação, depósito ou trading, acesse diretamente o suporte ao cliente.', 'При вопросах верификации, пополнения или торговли можно сразу обратиться в поддержку.', 'Пры пытаннях верыфікацыі, папаўнення або гандлю можна адразу звярнуцца ў падтрымку.', 'प्रमाणीकरण, जमा या ट्रेडिंग समस्या पर सीधे ग्राहक सहायता में जाएं।', 'عند مواجهة مشاكل التحقق أو الإيداع أو التداول يمكن الدخول مباشرة إلى قناة دعم العملاء.', 'عند مواجهة مشاكل التحقق أو الإيداع أو التداول يمكن الدخول مباشرة إلى قناة دعم العملاء.', 'Per problemi di verifica, deposito o trading, accedi direttamente all’assistenza clienti.', '首页高级交易');
INSERT IGNORE INTO `lang_mgr` (`lang_key`, `zh`, `en`, `tc`, `de`, `es`, `fr`, `idn`, `jp`, `ko`, `my`, `th`, `vi`, `pt`, `rus`, `blr`, `ida`, `sa`, `ar`, `it`, `remark`) VALUES ('home_adv_trust_flow', '风控确认', 'Risk-control confirmation', '風控確認', 'Risikokontrollbestätigung', 'Confirmación de control de riesgo', 'Confirmation du contrôle des risques', 'Konfirmasi kontrol risiko', 'リスク管理確認', '리스크 관리 확인', 'Pengesahan kawalan risiko', 'ยืนยันการควบคุมความเสี่ยง', 'Xác nhận kiểm soát rủi ro', 'Confirmação de controle de risco', 'Подтверждение риск-контроля', 'Пацвярджэнне рызыка-кантролю', 'रिस्क-कंट्रोल पुष्टि', 'تأكيد التحكم بالمخاطر', 'تأكيد التحكم بالمخاطر', 'Conferma controllo rischio', '首页高级交易');
INSERT IGNORE INTO `lang_mgr` (`lang_key`, `zh`, `en`, `tc`, `de`, `es`, `fr`, `idn`, `jp`, `ko`, `my`, `th`, `vi`, `pt`, `rus`, `blr`, `ida`, `sa`, `ar`, `it`, `remark`) VALUES ('home_adv_trust_flow_desc', '交易限制、密码、实名等校验继续由项目现有流程处理。', 'Trading limits, passwords, real-name verification, and other checks continue to use existing project flows.', '交易限制、密碼、實名等校驗繼續由專案現有流程處理。', 'Handelsbeschränkungen, Passwörter, Identitätsprüfung und weitere Prüfungen laufen weiter über bestehende Projektabläufe.', 'Límites de trading, contraseñas, verificación de identidad y otros controles siguen usando los flujos existentes.', 'Les limites de trading, mots de passe, vérification d’identité et autres contrôles suivent les processus existants.', 'Batas trading, kata sandi, verifikasi identitas, dan pemeriksaan lain tetap memakai alur proyek yang ada.', '取引制限、パスワード、本人確認などのチェックは既存フローで処理されます。', '거래 제한, 비밀번호, 실명 인증 등 검사는 기존 프로젝트 흐름으로 처리됩니다.', 'Had dagangan, kata laluan, pengesahan identiti dan semakan lain terus menggunakan aliran projek sedia ada.', 'ข้อจำกัดการเทรด รหัสผ่าน การยืนยันตัวตน และการตรวจสอบอื่น ๆ ใช้กระบวนการเดิมของโครงการต่อไป', 'Giới hạn giao dịch, mật khẩu, xác minh danh tính và các kiểm tra khác tiếp tục dùng quy trình hiện có.', 'Limites de trading, senhas, verificação de identidade e outras checagens continuam usando os fluxos existentes.', 'Торговые ограничения, пароли, верификация личности и другие проверки продолжают использовать существующие процессы.', 'Гандлёвыя абмежаванні, паролі, верыфікацыя асобы і іншыя праверкі працягваюць выкарыстоўваць існыя працэсы.', 'ट्रेडिंग सीमा, पासवर्ड, वास्तविक नाम सत्यापन आदि जांचें मौजूदा प्रक्रिया से चलती रहेंगी।', 'تستمر قيود التداول وكلمات المرور والتحقق من الهوية وغيرها من الفحوصات عبر العمليات الحالية.', 'تستمر قيود التداول وكلمات المرور والتحقق من الهوية وغيرها من الفحوصات عبر العمليات الحالية.', 'Limiti di trading, password, verifica identità e altri controlli continuano a usare i flussi esistenti.', '首页高级交易');
INSERT IGNORE INTO `lang_mgr` (`lang_key`, `zh`, `en`, `tc`, `de`, `es`, `fr`, `idn`, `jp`, `ko`, `my`, `th`, `vi`, `pt`, `rus`, `blr`, `ida`, `sa`, `ar`, `it`, `remark`) VALUES ('home_adv_final_title', '准备好进入更专业的交易界面了吗？', 'Ready to enter a more professional trading interface?', '準備好進入更專業的交易介面了嗎？', 'Bereit für eine professionellere Trading-Oberfläche?', '¿Listo para entrar en una interfaz de trading más profesional?', 'Prêt à accéder à une interface de trading plus professionnelle ?', 'Siap masuk ke antarmuka trading yang lebih profesional?', 'よりプロフェッショナルな取引画面に進む準備はできましたか？', '더 전문적인 거래 화면으로 들어갈 준비가 되셨나요?', 'Bersedia memasuki antara muka dagangan yang lebih profesional?', 'พร้อมเข้าสู่หน้าจอเทรดที่เป็นมืออาชีพมากขึ้นหรือยัง?', 'Sẵn sàng vào giao diện giao dịch chuyên nghiệp hơn?', 'Pronto para entrar em uma interface de trading mais profissional?', 'Готовы перейти к более профессиональному торговому интерфейсу?', 'Гатовы перайсці да больш прафесійнага гандлёвага інтэрфейсу?', 'क्या आप अधिक पेशेवर ट्रेडिंग इंटरफेस में प्रवेश करने के लिए तैयार हैं?', 'هل أنت مستعد للدخول إلى واجهة تداول أكثر احترافية؟', 'هل أنت مستعد للدخول إلى واجهة تداول أكثر احترافية؟', 'Pronto per entrare in una interfaccia di trading più professionale?', '首页高级交易');
INSERT IGNORE INTO `lang_mgr` (`lang_key`, `zh`, `en`, `tc`, `de`, `es`, `fr`, `idn`, `jp`, `ko`, `my`, `th`, `vi`, `pt`, `rus`, `blr`, `ida`, `sa`, `ar`, `it`, `remark`) VALUES ('home_adv_final_subtitle', '看行情、选资产、进入交易，首页先把关键路径摆清楚。', 'View markets, choose assets, and enter trading. The home page makes the key path clear first.', '看行情、選資產、進入交易，首頁先把關鍵路徑擺清楚。', 'Märkte ansehen, Assets auswählen und handeln: Die Startseite macht den wichtigsten Weg zuerst klar.', 'Ver mercados, elegir activos y entrar al trading: la página de inicio deja claro el camino principal.', 'Voir les marchés, choisir des actifs et passer au trading : l’accueil clarifie d’abord le parcours clé.', 'Lihat pasar, pilih aset, lalu masuk trading. Beranda menjelaskan jalur utama terlebih dahulu.', '相場を見て、資産を選び、取引へ進む。ホームが重要な導線を先に明確にします。', '시세를 보고, 자산을 선택하고, 거래로 진입합니다. 홈에서 핵심 경로를 먼저 명확히 보여줍니다.', 'Lihat pasaran, pilih aset dan masuk dagangan. Laman utama menjelaskan laluan utama terlebih dahulu.', 'ดูตลาด เลือกสินทรัพย์ แล้วเข้าสู่การเทรด หน้าแรกแสดงเส้นทางสำคัญให้ชัดเจนก่อน', 'Xem thị trường, chọn tài sản và vào giao dịch. Trang chủ làm rõ lộ trình chính trước tiên.', 'Veja mercados, escolha ativos e entre no trading. A página inicial deixa claro o caminho principal.', 'Смотрите рынки, выбирайте активы и переходите к торговле. Главная сначала показывает ключевой путь.', 'Глядзіце рынкі, выбірайце актывы і пераходзьце да гандлю. Галоўная спачатку паказвае ключавы шлях.', 'मार्केट देखें, एसेट चुनें और ट्रेडिंग में जाएं। होम पेज पहले मुख्य रास्ता स्पष्ट करता है।', 'شاهد الأسواق واختر الأصول وادخل التداول. توضّح الصفحة الرئيسية المسار الأساسي أولًا.', 'شاهد الأسواق واختر الأصول وادخل التداول. توضّح الصفحة الرئيسية المسار الأساسي أولًا.', 'Guarda i mercati, scegli gli asset ed entra nel trading. La home chiarisce prima il percorso principale.', '首页高级交易');
